long media_enum_entities(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent = { };
    struct media_entity *entity;
    int ret;

    if (!mdev || !uent)
        return -EINVAL;

    entity = media_entity_get_by_id(mdev, kent.id);
    if (!entity)
        return -ENOENT;

    kent.flags = entity->flags;
    kent.pads = entity->num_pads;
    kent.links = entity->num_links;
    strcpy(kent.name, entity->name);

    if (copy_to_user(uent, &kent, sizeof(kent)))
        return -EFAULT;

    return 0;
}

long media_entity_enum(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc desc;
    struct media_entity *entity;
    __u32 id;
    int ret;

    if (get_user(id, &uent->id))
        return -EFAULT;

    entity = media_entity_get(mdev, id);
    if (!entity)
        return -EINVAL;

    memset(&desc, 0, sizeof(desc));
    desc.id = entity->id;
    desc.name = entity->name;
    desc.type = entity->type;
    desc.revision = entity->revision;
    desc.flags = entity->flags;
    desc.padding = 0;

    if (copy_to_user(uent, &desc, sizeof(desc))) {
        media_entity_put(entity);
        return -EFAULT;
    }

    media_entity_put(entity);
    return 0;
}

long enumerate_and_copy_media_entity(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent;
    int index;
    int ret;

    if (!mdev || !uent)
        return -EINVAL;

    index = 0; // Assuming enumeration starts from index 0
    while (index < mdev->entity_count) {
        struct media_entity *entity = &mdev->entities[index];

        // Initialize the user entity descriptor
        memset(&kent, 0, sizeof(kent));
        kent.id = entity->id;
        strncpy(kent.name, entity->name, sizeof(kent.name) - 1);
        kent.name[sizeof(kent.name) - 1] = '\0';
        kent.type = entity->type;
        kent.revision = entity->revision;
        kent.flags = entity->flags;

        ret = copy_to_user(uent, &kent, sizeof(kent));
        if (ret)
            return -EFAULT;

        index++;
    }

    return 0;
}

long enumerate_media_entity(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent;
    int ret;

    if (!mdev || !uent)
        return -EINVAL;

    memset(&kent, 0, sizeof(kent));

    ret = media_entity_get(mdev, &kent);
    if (ret < 0)
        return ret;

    if (copy_to_user(uent, &kent, sizeof(kent)))
        return -EFAULT;

    return 0;
}
